"""Classify credential-like hits in private memory repo. Never print secret values."""
import re, subprocess, hashlib
from pathlib import Path
from collections import defaultdict

root = Path('.').resolve()
files = subprocess.check_output(['git','ls-files'], text=True).splitlines()

# patterns that look like real secrets being assigned
assign_re = re.compile(
    r'(?i)(?:password|passwd|pwd|secret|token|api[_-]?key|access[_-]?key)\s*[=:]\s*[\'\"]?([^\s\'\"#,;]{4,})'
)
# known bad literals from company repo (hash check only)
known = {
    '***REDACTED***': 'dev_shared',
    '***REDACTED***': 'sr_admin',
}
known_h = {hashlib.sha256(k.encode()).hexdigest()[:16]: v for k,v in known.items()}

# allow placeholders
allow = re.compile(r'(?i)^(your-password|changeme|placeholder|\*+|xxx+|TODO|None|null|true|false|\$\{.+\}|<.*>|os\.environ|getenv|getpass|process\.env|PASSWORD|password|passwd)$')

# meeting room style short codes in 群 messages often 密码：***REDACTED*** — still redact if looks like credential context for DB
# We'll flag DB-ish context separately

cats = defaultdict(list)  # category -> [(file, kind, len, preview_type)]

def classify_value(val, line):
    h = hashlib.sha256(val.encode()).hexdigest()[:16]
    if h in known_h:
        return f'known_{known_h[h]}'
    if allow.match(val):
        return 'placeholder'
    # meeting password in lark (密码： ***REDACTED*** alphanumeric)
    if re.search(r'密码[：:]', line) and len(val) <= 16 and re.match(r'^[A-Za-z0-9@!#._-]+$', val):
        if 'lark' in line.lower() or '会议' in line or 'PRD' in line or '链接' in line:
            return 'meeting_code'
    # jdbc/mysql/cnf style
    if re.search(r'(?i)(mysql|starrocks|jdbc|my\.cnf|defaults_file|readonly_user|\badmin\b)', line):
        return 'db_credential'
    if re.search(r'(?i)(telegram|bot.?token|api[_-]?key|openai|gptproto)', line):
        return 'api_token'
    if val.startswith('ghp_') or val.startswith('github_pat_') or val.startswith('sk-'):
        return 'api_token'
    if re.search(r'(?i)password\s*[=:]', line) and len(val) >= 6:
        return 'password_assign'
    return 'other'

for f in files:
    p = root / f
    if not p.is_file():
        continue
    # skip binary-ish
    try:
        text = p.read_text(encoding='utf-8', errors='ignore')
    except Exception:
        continue
    # whole-file known secret scan
    for k, name in known.items():
        if k in text:
            cats[f'known_{name}'].append((f, 'literal', len(k)))
    for m in assign_re.finditer(text):
        val = m.group(1).rstrip('\'\"')
        # find line
        start = text.rfind('\n', 0, m.start()) + 1
        end = text.find('\n', m.end())
        if end < 0: end = len(text)
        line = text[start:end]
        kind = classify_value(val, line)
        cats[kind].append((f, kind, len(val)))

print('=== summary by category (file counts) ===')
for k in sorted(cats):
    files_hit = sorted(set(x[0] for x in cats[k]))
    print(f'{k}: {len(cats[k])} hits in {len(files_hit)} files')
    for ff in files_hit[:15]:
        print(f'  - {ff}')
    if len(files_hit) > 15:
        print(f'  ... +{len(files_hit)-15} more')

# inspect .env tracked files keys only
print('\n=== tracked *.env keys (no values) ===')
for f in files:
    if f.endswith('.env') or f.endswith('.env.example'):
        keys=[]
        for line in (root/f).read_text(errors='ignore').splitlines():
            if not line.strip() or line.strip().startswith('#'):
                continue
            if '=' in line:
                k,v=line.split('=',1)
                keys.append(f'{k.strip()}=***len{len(v.strip())}')
        print(f, keys[:20])

# onehr script
print('\n=== onehr_checkin_auto.py password context (masked) ===')
p=root/'scripts/onehr_checkin_auto.py'
if p.exists():
    for i,l in enumerate(p.read_text().splitlines(),1):
        if re.search(r'(?i)password|passwd|pwd|secret|token', l):
            # mask after =
            masked=re.sub(r'(=\s*)([^\s\'\"]+)', r'\1***', l)
            masked=re.sub(r'(["\'])([^"\']{4,})(["\'])', r'\1***\3', masked)
            print(f'{i}:{masked[:120]}')
