"""Redact plaintext credentials in private memory repo. Commit-ready."""
from __future__ import annotations
import re
import subprocess
from pathlib import Path

ROOT = Path('.').resolve()

# Exact known secrets from company-leak discussion (and any still in mirrors)
KNOWN = [
    '***REDACTED***',
    '***REDACTED***',
]

# password/passwd/pwd / secret / token / api_key assignments with real-looking values
ASSIGN_RE = re.compile(
    r'(?i)(\b(?:password|passwd|pwd|secret|api[_-]?key|access[_-]?key|bot[_-]?token|auth[_-]?token)\b\s*[=:]\s*)([\'\"]?)([^\'\"\s#,;]{4,})(\2)'
)
# bare known strings
# also: password: XXX in yaml-like without word boundary issues

ALLOW_VAL = re.compile(
    r'(?i)^(your-password|your_password|changeme|placeholder|\*+|x{3,}|TODO(_PASSWORD)?|None|null|true|false|'
    r'\$\{[^}]+\}|<[^>]+>|PASSWORD|password|passwd|secret|token|REDACTED|\*\*\*REDACTED\*\*\*|'
    r'os\.environ|getenv|getpass|process\.env|ONEHR_PASSWORD|<.*>)$'
)

# Chinese 密码：***REDACTED*** (meeting codes + accidental dumps) — redact non-trivial
CN_PWD_RE = re.compile(r'(密码[：:]\s*)([A-Za-z0-9@!#._\-]{4,})')

REDACT = '***REDACTED***'

def should_skip_path(f: str) -> bool:
    # keep example templates that only have placeholders — still run, allowlist protects
    if f.endswith('.png') or f.endswith('.jpg'):
        return True
    return False

def redact_text(text: str) -> tuple[str, int]:
    n = 0
    for k in KNOWN:
        if k in text:
            c = text.count(k)
            text = text.replace(k, REDACT)
            n += c

    def repl_assign(m: re.Match) -> str:
        nonlocal n
        prefix, q, val, q2 = m.group(1), m.group(2), m.group(3), m.group(4)
        if ALLOW_VAL.match(val):
            return m.group(0)
        # keep short boolean-like
        if len(val) < 4:
            return m.group(0)
        n += 1
        return f'{prefix}{q}{REDACT}{q2}'

    text2, _ = ASSIGN_RE.subn(repl_assign, text)
    text = text2

    def repl_cn(m: re.Match) -> str:
        nonlocal n
        # keep very short meeting? still redact per iron rule for 账号密码; meeting codes also shouldn't sync
        n += 1
        return m.group(1) + REDACT

    text, c2 = CN_PWD_RE.subn(repl_cn, text)
    # c2 already counted in repl via nonlocal — wait, subn calls repl which increments n, so don't add c2 again
    return text, n

files = subprocess.check_output(['git', 'ls-files'], text=True).splitlines()
changed = []
total = 0
for f in files:
    if should_skip_path(f):
        continue
    p = ROOT / f
    if not p.is_file():
        continue
    try:
        raw = p.read_bytes()
    except Exception:
        continue
    # skip obvious binary
    if b'\0' in raw[:4096]:
        continue
    try:
        text = raw.decode('utf-8')
    except UnicodeDecodeError:
        try:
            text = raw.decode('utf-8', errors='ignore')
        except Exception:
            continue
    new, n = redact_text(text)
    if n and new != text:
        p.write_text(new, encoding='utf-8')
        changed.append((f, n))
        total += n

print(f'redacted_replacements={total} files_changed={len(changed)}')
for f, n in sorted(changed, key=lambda x: -x[1])[:40]:
    print(f'  {n:4d}  {f}')
if len(changed) > 40:
    print(f'  ... +{len(changed)-40} more files')

# verify known gone
left = []
for f in files:
    p = ROOT / f
    if not p.is_file():
        continue
    try:
        t = p.read_text(encoding='utf-8', errors='ignore')
    except Exception:
        continue
    for k in KNOWN:
        if k in t:
            left.append(f)
            break
print('known_secrets_remaining_files', len(left))
for f in left[:10]:
    print('  STILL', f)
